निम्नलिखित C कोड का आउटपुट क्या होगा?

#include <stdio.h>
int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int *p = (int*)(&arr + 1);
    printf("%d", *(p - 2));
    return 0;
}

C में सरणी इंडेक्सिंग की क्रमविनिमेयता दर्शाने वाले निम्नलिखित कोड का आउटपुट क्या होगा?

#include <stdio.h>
int main() {
    int a[] = {5, 10, 15, 20};
    printf("%d", 2[a]);
    return 0;
}

निम्नलिखित C कोड का व्यवहार क्या होगा?

#include <stdio.h>
#include <stdlib.h>
int main() {
    int *p = (int*)malloc(sizeof(int));
    *p = 100;
    free(p);
    *p = 200;
    printf("%d", *p);
    return 0;
}

निम्नलिखित C++ कोड का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
class Test {
    static int count;
public:
    Test() { count++; }
    static int getCount() { return count; }
};
int Test::count = 0;
int main() {
    Test t1, t2, t3;
    cout << Test::getCount();
    return 0;
}

निम्नलिखित C++ प्रोग्राम का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
class A {
public:
    virtual void print() { cout << "A "; }
};
class B : public A {
public:
    void print() override { cout << "B "; }
};
class C : public B {
public:
    void print() override { cout << "C "; }
};
int main() {
    A *obj = new C();
    obj->print();
    return 0;
}

निम्नलिखित स्निपेट का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
int main() {
    int i = 0;
    for (i = 0; i < 5; i++) {
        if (i == 2) continue;
        if (i == 4) break;
        cout << i << " ";
    }
    return 0;
}

निम्नलिखित कोड का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
void modify(const int *p) {
    int *q = const_cast<int*>(p);
    *q = 50;
}
int main() {
    int val = 10;
    modify(&val);
    cout << val;
    return 0;
}
